[[nodiscard]] constexpr const ElementParameters* find_element(std::uint32_t atomic_number) noexcept {
  return atomic_number >= 1u && atomic_number <= kElementCount ? &kElements[atomic_number - 1u] : nullptr;
}

[[nodiscard]] constexpr double pair_scale(std::uint32_t first, std::uint32_t second) noexcept {
  for (const auto& value : kPairScaleOverrides) {
    if ((value.first_atomic_number == first && value.second_atomic_number == second) ||
        (value.first_atomic_number == second && value.second_atomic_number == first)) return value.value;
  }
  return kGlobal.pair_scale_default;
}

